using System.Security.Cryptography;
using System.Text.Json;
using CouponBook.Data;
using CouponBook.Data.Entities;
using Microsoft.EntityFrameworkCore;
namespace CouponBook.Business.Sales;

using CouponBook.Business.Auth;
public interface IPurchaseService
{
    Task<ServiceResult<PurchaseStarted>> StartPurchaseAsync(int userId, int bookId, PurchaseRequestData? request = null);
    Task<ServiceResult<WebhookOutcome>> HandleWebhookAsync(string rawBody, string? signature, string? ip);
    Task<OrderDto?> GetOrderAsync(int userId, int orderId); Task<List<MyBookDto>> GetMyBooksAsync(int userId); Task<PaymentRef?> GetOwnPaymentAsync(int userId, int paymentId);
}
public class PurchaseService : IPurchaseService
{
    private readonly AppDbContext _db; private readonly IPaymentProvider _provider; public PurchaseService(AppDbContext db, IPaymentProvider provider) { _db = db; _provider = provider; }
    public async Task<ServiceResult<PurchaseStarted>> StartPurchaseAsync(int userId, int bookId, PurchaseRequestData? request = null)
    {
        request ??= new PurchaseRequestData(null, false, null, null, "card"); var now = DateTime.UtcNow;
        var book = await _db.Books.Include(x => x.Vouchers).FirstOrDefaultAsync(b => b.Id == bookId && b.Status == BookStatus.Published && b.SaleStartAt <= now && b.SaleEndAt >= now); if (book == null || book.Vouchers.Count == 0) return ServiceResult<PurchaseStarted>.Fail("book_unavailable");
        var sold = await _db.PurchasedBooks.CountAsync(x => x.BookId == bookId && x.Status != PurchasedBookStatus.Refunded); if (book.Vouchers.Any(v => sold >= v.ProviderQuota)) return ServiceResult<PurchaseStarted>.Fail("sold_out");
        if (request.IsGift && string.IsNullOrWhiteSpace(request.RecipientMobile)) return ServiceResult<PurchaseStarted>.Fail("gift_mobile_required");
        decimal discount = 0; PromoCode? promo = null;
        if (!string.IsNullOrWhiteSpace(request.PromoCode)) { promo = await _db.PromoCodes.Include(x => x.Books).FirstOrDefaultAsync(x => x.Code == request.PromoCode && x.IsActive); if (promo == null || promo.ValidFrom > now || promo.ValidTo < now || (promo.Books.Count > 0 && !promo.Books.Any(x => x.BookId == bookId))) return ServiceResult<PurchaseStarted>.Fail("invalid_promo"); var total = await _db.PromoCodeUsages.CountAsync(x => x.PromoCodeId == promo.Id); var mine = await _db.PromoCodeUsages.CountAsync(x => x.PromoCodeId == promo.Id && x.UserId == userId); if (total >= promo.TotalUsageLimit || mine >= promo.PerCustomerLimit) return ServiceResult<PurchaseStarted>.Fail("promo_used_up"); discount = promo.DiscountType == PromoDiscountType.Percentage ? Math.Round(book.Price * (promo.DiscountValue / 100m), 3) : promo.DiscountValue; if (book.Price - discount <= 0) return ServiceResult<PurchaseStarted>.Fail("promo_zero_price"); }
        await using var tx = await _db.Database.BeginTransactionAsync(); var order = new Order { BuyerUserId = userId, BookId = bookId, PromoCodeId = promo?.Id, Subtotal = book.Price, DiscountAmount = discount, Amount = book.Price - discount, PaymentMethod = request.PaymentMethod, IsGift = request.IsGift }; _db.Orders.Add(order); await _db.SaveChangesAsync();
        if (request.IsGift) _db.Gifts.Add(new Gift { OrderId = order.Id, SenderUserId = userId, RecipientMobile = request.RecipientMobile!, Message = request.GiftMessage });
        var session = _provider.CreateSession(order.Id, order.Amount, order.Currency); var payment = new Payment { OrderId = order.Id, Provider = _provider.Name, ProviderTxnId = session.ProviderTxnId, Amount = order.Amount, Method = request.PaymentMethod, IdempotencyKey = Guid.NewGuid().ToString("N") }; _db.Payments.Add(payment); await _db.SaveChangesAsync(); await tx.CommitAsync();
        return ServiceResult<PurchaseStarted>.Ok(new(order.Id, order.Status.ToString(), order.Subtotal, order.DiscountAmount, order.Amount, order.Currency, new(payment.Id, payment.Provider, session.PaymentUrl)));
    }
    public async Task<ServiceResult<WebhookOutcome>> HandleWebhookAsync(string rawBody, string? signature, string? ip) { WebhookPayload payload; try { payload = _provider.VerifyWebhook(rawBody, signature); } catch (WebhookRejectedException ex) { Audit(null, "PAYMENT_WEBHOOK", "Payment", "", "REJECTED", ex.Message, ip); await _db.SaveChangesAsync(); return ServiceResult<WebhookOutcome>.Fail("webhook_rejected", new[] { ex.Message }); } return await Process(payload, ip); }
    private async Task<ServiceResult<WebhookOutcome>> Process(WebhookPayload payload, string? ip) { var ok = payload.Status.Equals("SUCCEEDED", StringComparison.OrdinalIgnoreCase); var fail = payload.Status.Equals("FAILED", StringComparison.OrdinalIgnoreCase); if (!ok && !fail) return ServiceResult<WebhookOutcome>.Fail("invalid_status"); await using var tx = await _db.Database.BeginTransactionAsync(); var payment = (await _db.Payments.FromSqlInterpolated($"SELECT * FROM \"Payments\" WHERE \"Provider\"={_provider.Name} AND \"ProviderTxnId\"={payload.ProviderTxnId} FOR UPDATE").ToListAsync()).FirstOrDefault(); if (payment == null) return ServiceResult<WebhookOutcome>.Fail("unknown_transaction"); var order = await _db.Orders.Include(x => x.Book).ThenInclude(x => x.Vouchers).Include(x => x.Gift).FirstAsync(x => x.Id == payment.OrderId); if (payment.Status != PaymentStatus.Pending) return ServiceResult<WebhookOutcome>.Ok(new("duplicate", order.Id, order.Status.ToString())); if (payload.Amount != payment.Amount) return ServiceResult<WebhookOutcome>.Fail("amount_mismatch"); if (fail) { payment.Status = PaymentStatus.Failed; order.Status = OrderStatus.Failed; } else { payment.Status = PaymentStatus.Paid; payment.PaidAt = DateTime.UtcNow; order.Status = OrderStatus.Paid; order.PaidAt = payment.PaidAt; await Activate(order); if (order.PromoCodeId != null) _db.PromoCodeUsages.Add(new PromoCodeUsage { PromoCodeId = order.PromoCodeId.Value, UserId = order.BuyerUserId, OrderId = order.Id, DiscountAmount = order.DiscountAmount }); } Audit(order.BuyerUserId, "PAYMENT_WEBHOOK", "Order", order.Id.ToString(), ok ? "SUCCESS" : "FAILED", null, ip); await _db.SaveChangesAsync(); await tx.CommitAsync(); return ServiceResult<WebhookOutcome>.Ok(new("processed", order.Id, order.Status.ToString())); }
    private async Task Activate(Order order)
    {
        int? ownerId = order.IsGift ? null : order.BuyerUserId; if (order.IsGift && order.Gift != null) { var recipient = await _db.Users.FirstOrDefaultAsync(x => x.PhoneNumber == order.Gift.RecipientMobile); if (recipient != null) { ownerId = recipient.Id; order.Gift.RecipientUserId = recipient.Id; order.Gift.Status = GiftStatus.Claimed; order.Gift.ClaimedAt = DateTime.UtcNow; } }
        var purchasedAt = order.PaidAt ?? DateTime.UtcNow; var pb = new PurchasedBook { OwnerUserId = ownerId, BookId = order.BookId, OrderId = order.Id, GiftId = order.Gift?.Id, PurchasedAt = purchasedAt, ExpiresAt = purchasedAt.AddDays(order.Book.ValidityDays), BookTitleSnapshot = order.Book.Title, PriceSnapshot = order.Amount, Vouchers = order.Book.Vouchers.Select(v => new CustomerVoucher { VoucherId = v.Id, Code = GenerateCode(), UsageLimitSnapshot = v.UsageLimit, UsesRemaining = v.UsageLimit, FaceValueSnapshot = v.FaceValue, TitleSnapshot = v.Title, TermsSnapshot = v.Terms, ExpiresAt = purchasedAt.AddDays(order.Book.ValidityDays) }).ToList() }; _db.PurchasedBooks.Add(pb); if (ownerId != null) _db.Notifications.Add(new Notification { UserId = ownerId.Value, Type = order.IsGift ? "gift_received" : "purchase_confirmed", Title = order.IsGift ? "Gift received" : "Purchase confirmed", Body = $"{order.Book.Title} is now active." });
    }
    private static string GenerateCode() => Convert.ToBase64String(RandomNumberGenerator.GetBytes(24)).Replace('+', '-').Replace('/', '_').TrimEnd('=');
    private void Audit(int? uid, string action, string type, string id, string result, string? reason = null, string? ip = null) => _db.AuditLogs.Add(new AuditLog { UserId = uid, Action = action, EntityType = type, EntityId = id, Result = result, Reason = reason, Ip = ip });
    public Task<OrderDto?> GetOrderAsync(int uid, int oid) => _db.Orders.AsNoTracking().Where(x => x.Id == oid && x.BuyerUserId == uid).Select(x => new OrderDto(x.Id, x.BookId, x.Subtotal, x.DiscountAmount, x.Amount, x.Currency, x.Status, x.IsGift, x.CreatedAt, x.PaidAt)).FirstOrDefaultAsync();
    public Task<List<MyBookDto>> GetMyBooksAsync(int uid) => _db.PurchasedBooks.AsNoTracking().Where(x => x.OwnerUserId == uid).OrderByDescending(x => x.Id).Select(x => new MyBookDto(x.Id, x.BookTitleSnapshot, x.Status, x.PurchasedAt, x.ExpiresAt, x.Gift == null ? null : x.Gift.Sender.FullName, x.Vouchers.Select(v => new MyCouponDto(v.Id, v.Code, v.TitleSnapshot, v.Voucher.Provider.Name, v.UsesRemaining, v.UsageLimitSnapshot, v.Status, v.ExpiresAt)).ToList())).ToListAsync();
    public Task<PaymentRef?> GetOwnPaymentAsync(int uid, int pid) => _db.Payments.AsNoTracking().Where(x => x.Id == pid && x.Order.BuyerUserId == uid).Select(x => new PaymentRef(x.ProviderTxnId ?? "", x.Amount)).FirstOrDefaultAsync();
}
